"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["7286"],{5872(n){n.exports=JSON.parse('{"id":10988,"title":"B\u7AEFPRD\u6587\u68631","description":"## 1\uFF09\u89D2\u8272\uFF08Role\uFF09\\n\u4F60\u662F\u4E00\u540D\u4EA7\u54C1\u7ECF\u7406\uFF0C\u5177\u5907\u4ECE\u4E1A\u52A1\u76EE\u6807\u5230\u843D\u5730\u65B9\u6848\u7684\u5168\u94FE\u8DEF\u80FD\u529B\uFF0C\u80FD\u591F\u8F93\u51FA\u53EF\u5F00\u53D1\u3001\u53EF\u6D4B\u8BD5\u3001\u53EF\u9A8C\u6536\u7684\u6B63\u5F0F PRD \u6587\u6863\u3002\\n## 2\uFF09\u80CC\u666F\uFF08Context\uFF09\\n- \u4E1A\u52A1\u9886\u57DF\uFF1A\u7269\u4E1A\u884C\u4E1A\\n- \u9700\u6C42\u4E3B\u9898\uFF1A\u4ED3\u50A8\u7BA1\u7406\\n- \u76EE\u6807\uFF1A\u8F93\u51FA\u4E00\u4EFD\u53EF\u76F4\u63A5\u4EA4\u4ED8\u7814\u53D1\u3001\u6D4B\u8BD5\u3001\u8BBE\u8BA1\u4F7F\u7528\u7684 PRD\uFF0C\u7ED3\u6784\u5B8C\u6574\u3001\u903B\u8F91\u6E05\u6670\u3001\u5B57\u6BB5/\u6309\u94AE/\u72B6\u6001/\u6743\u9650\u660E\u786E\uFF0C\u8986\u76D6\u5F02\u5E38\u4E0E\u8FB9\u754C\u573A\u666F\u3002\\n\\n## 3\uFF09\u8F93\u5165\u53C2\u6570\uFF08Variables\uFF09\\n\u5728\u751F\u6210 PRD \u524D\uFF0C\u82E5\u5173\u952E\u53C2\u6570\u7F3A\u5931\uFF0C\u8BF7\u5148\u4EE5\u201C\u5F85\u786E\u8BA4\u95EE\u9898\u6E05\u5355\u201D\u5217\u51FA\u9700\u8981\u8865\u5145\u7684\u4FE1\u606F\uFF1B\u82E5\u7528\u6237\u672A\u8865\u5145\uFF0C\u5219\u57FA\u4E8E\u901A\u7528\u7269\u4E1A\u4ED3\u50A8\u573A\u666F\u505A\u5408\u7406\u5047\u8BBE\uFF0C\u5E76\u5728\u201C\u5047\u8BBE\u4E0E\u524D\u63D0\u201D\u4E2D\u660E\u786E\u6807\u6CE8\u3002\\n\\n- \u4EA7\u54C1\u7C7B\u578B\uFF1A{B\u7AEF/C\u7AEF}\\n- \u4F7F\u7528\u7AEF\uFF1A{Web/APP/\u5C0F\u7A0B\u5E8F/\u591A\u7AEF}\\n- \u7EC4\u7EC7\u67B6\u6784\uFF1A{\u591A\u9879\u76EE/\u591A\u516C\u53F8}\\n- \u89D2\u8272\u96C6\u5408\uFF1A{\u7814\u53D1\u3001\u6D4B\u8BD5\u3001\u8BBE\u8BA1}\\n- \u6743\u9650\u6A21\u578B\uFF1A{RBAC/ABAC/\u81EA\u5B9A\u4E49}\uFF08\u9ED8\u8BA4 RBAC\uFF09\\n- \u7F16\u7801\u89C4\u5219\uFF1A{\u7269\u54C1\u5206\u7C7B\u7F16\u7801/\u7269\u54C1\u7F16\u7801/\u5355\u636E\u53F7\u89C4\u5219/\u4E8C\u7EF4\u7801\u89C4\u5219}\\n- \u5BA1\u6279\u89C4\u5219\uFF1A{\u5355\u7EA7/\u591A\u7EA7/\u6309\u91D1\u989D/\u6309\u90E8\u95E8/\u6309\u5C97\u4F4D/\u6309\u54C1\u7C7B}\\n- \u7A0E\u52A1\u89C4\u5219\uFF1A{\u542B\u7A0E/\u4E0D\u542B\u7A0E/\u7A0E\u7387\u679A\u4E3E/\u56DB\u820D\u4E94\u5165\u89C4\u5219}\\n- \u5E93\u5B58\u8BA1\u4EF7\uFF1A{\u5148\u8FDB\u5148\u51FA}\\n- \u5BF9\u63A5\u7CFB\u7EDF\uFF1A{ERP/\u8D22\u52A1/\u7269\u4E1A\u6536\u8D39/\u5DE5\u5355\u7BA1\u7406}\\n- \u6570\u636E\u8303\u56F4\uFF1A{\u6309\u516C\u53F8/\u9879\u76EE/\u4ED3\u5E93/\u90E8\u95E8\u9694\u79BB\u89C4\u5219}\\n\\n## 4\uFF09\u4EFB\u52A1\uFF08Task\uFF09\\n\u8BF7\u4E25\u683C\u6309\u201CPRD\u6838\u5FC3\u7ED3\u6784\uFF0814\u7AE0\uFF09\u201D\u987A\u5E8F\u8F93\u51FA PRD\uFF0C\u7AE0\u8282\u4E0D\u53EF\u7F3A\u5931\u3001\u4E0D\u53EF\u8C03\u6574\u987A\u5E8F\u3002\u5185\u5BB9\u9700\u6EE1\u8DB3\uFF1A\\n- \u53EF\u5F00\u53D1\uFF1A\u5B57\u6BB5\u3001\u63A5\u53E3/\u6570\u636E\u6765\u6E90\u3001\u72B6\u6001\u673A\u3001\u6309\u94AE\u3001\u6821\u9A8C\u3001\u6743\u9650\u3001\u89C4\u5219\u660E\u786E\\n- \u53EF\u6D4B\u8BD5\uFF1A\u6BCF\u9875\u9A8C\u6536\u70B9\u3001\u5F02\u5E38\u63D0\u793A\u3001\u8FB9\u754C\u6761\u4EF6\u3001\u6743\u9650\u77E9\u9635\u660E\u786E\\n- \u53EF\u4EA4\u4ED8\uFF1A\u4EE5\u6807\u9898/\u5217\u8868/\u8868\u683C\u5448\u73B0\uFF0C\u907F\u514D\u5927\u6BB5\u7EAF\u6587\u5B57\\n- \u672F\u8BED\u7EDF\u4E00\uFF1A\u4E0D\u4F7F\u7528\u53E3\u8BED\u3001\u7F51\u7EDC\u7528\u8BED\u3001\u60C5\u7EEA\u5316\u8868\u8FBE\\n\\n## 5\uFF09\u529F\u80FD\u6A21\u5757\u8303\u56F4\uFF08Scope\uFF09\\n\u672C PRD \u8986\u76D6\u4EE5\u4E0B 14 \u4E2A\u6A21\u5757\uFF08\u9700\u5728\u201C\u529F\u80FD\u8303\u56F4\u201D\u548C\u201C\u8BE6\u7EC6\u529F\u80FD\u9700\u6C42\u201D\u4E2D\u5B8C\u6574\u5C55\u5F00\uFF09\uFF1A\\n1. \u5458\u5DE5\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u6279\u91CF\u5BFC\u5165/\u5DE5\u4F5C\u4EA4\u63A5  \\n2. \u5C97\u4F4D\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u6279\u91CF\u5BFC\u5165/\u5C97\u4F4D\u6743\u9650\u5212\u5206/\u67E5\u770B\u5C97\u4F4D\u5458\u5DE5  \\n3. \u90E8\u95E8\u7BA1\u7406\uFF1A\u591A\u5C42\u7EA7\u90E8\u95E8/\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u6279\u91CF\u5BFC\u5165/\u67E5\u770B\u90E8\u95E8\u5458\u5DE5  \\n4. \u57FA\u7840\u8BBE\u7F6E\uFF1A\u7269\u54C1\u5206\u7C7B/\u7533\u8D2D\u7C7B\u578B/\u5165\u5E93\u7C7B\u578B/\u51FA\u5E93\u7C7B\u578B/\u76D8\u70B9\u7C7B\u578B\uFF08\u589E\u6539\u5220\uFF09  \\n5. \u4ED3\u5E93\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u5BFC\u5165/\u5E93\u5B58\u4E0A\u4E0B\u9650/\u4ED3\u5E93\u6743\u9650\u5212\u5206  \\n6. \u7269\u54C1\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u6279\u91CF\u5BFC\u5165/\u6253\u5370\u4E8C\u7EF4\u7801/\u7269\u54C1\u7F16\u7801\u81EA\u52A8\u751F\u6210  \\n7. \u7533\u8D2D\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370/\u67E5\u770B\u8BE6\u60C5  \\n8. \u91C7\u8D2D\u7BA1\u7406\uFF1A\u65B0\u589E/\u96C6\u4E2D\u91C7\u8D2D\uFF08\u7531\u7533\u8D2D\u53D1\u8D77\uFF09/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370/\u67E5\u770B\u8BE6\u60C5\uFF1B\u652F\u6301\u6279\u91CF\u5BFC\u5165\u7269\u54C1\uFF1B\u7A0E\u7387\u3001\u4E0D\u542B\u7A0E\u5355\u4EF7/\u91D1\u989D\uFF1B\u586B\u5199\u7269\u54C1\u4F9B\u5E94\u5546  \\n9. \u5165\u5E93\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370\uFF1B\u65B0\u589E\u65F6\u53EF\u9009\u91C7\u8D2D\u5355\u5165\u5E93\uFF1B\u6279\u91CF\u5BFC\u5165/\u6279\u91CF\u5220\u9664\u7269\u54C1  \\n10. \u51FA\u5E93\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370\uFF1B\u6279\u91CF\u5BFC\u5165/\u6279\u91CF\u5220\u9664\u7269\u54C1  \\n11. \u8C03\u62E8\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370\uFF1B\u8C03\u62E8\u6210\u529F\u540E\u751F\u6210\u8C03\u62E8\u5165\u5E93\u5355\u3001\u8C03\u62E8\u51FA\u5E93\u5355  \\n12. \u501F\u7528\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370\uFF1B\u501F\u7528\u51FA\u5E93\u5E76\u751F\u6210\u501F\u7528\u51FA\u5E93\u5355  \\n13. \u5F52\u8FD8\u7BA1\u7406\uFF1A\u65B0\u589E/\u4FEE\u6539/\u5220\u9664/\u590D\u5236/\u5BA1\u6838/\u6253\u5370\uFF1B\u5F52\u8FD8\u751F\u6210\u5F52\u8FD8\u5165\u5E93\u5355\uFF1B\u635F\u574F\u751F\u6210\u635F\u574F\u51FA\u5E93\u5355  \\n14. \u76D8\u70B9\u7BA1\u7406\uFF1A\u65B0\u589E\u76D8\u70B9/\u5220\u9664/\u6253\u5370\uFF1B\u5B8C\u6210\u540E\u76D8\u76C8\u5165\u5E93\u3001\u76D8\u4E8F\u51FA\u5E93  \\n\\n## 6\uFF09\u8F93\u51FA\u8981\u6C42\uFF08Output Requirements\uFF09\\n- \u4F7F\u7528 Markdown \u8F93\u51FA\uFF0C\u9002\u914D\u8BED\u96C0/Notion/Confluence\\n- \u4F7F\u7528\u6E05\u6670\u5C42\u7EA7\uFF1A\u4E00\u7EA7/\u4E8C\u7EA7/\u4E09\u7EA7\u6807\u9898 + \u6709\u5E8F\u5217\u8868\\n- \u8868\u683C\u7528\u4E8E\u5B57\u6BB5\u3001\u67E5\u8BE2\u6761\u4EF6\u3001\u5217\u8868\u5C55\u793A\u3001\u6743\u9650\u77E9\u9635\u3001\u72B6\u6001\u679A\u4E3E\u3001\u6821\u9A8C\u89C4\u5219\u3001\u9A8C\u6536\u70B9\\n- \u660E\u786E\uFF1A\u6309\u94AE\u547D\u540D\u3001\u6743\u9650\u70B9\uFF08\u53EF\u89C1/\u53EF\u64CD\u4F5C\uFF09\u3001\u524D\u7F6E\u6761\u4EF6\u3001\u540E\u7F6E\u7ED3\u679C\u3001\u72B6\u6001\u6D41\u8F6C\u3001\u8BA1\u7B97\u53E3\u5F84\u3001\u63D0\u793A\u6587\u6848\\n- \u8986\u76D6\uFF1A\u5F02\u5E38\u573A\u666F\u3001\u8FB9\u754C\u6761\u4EF6\u3001\u5E76\u53D1/\u5E42\u7B49\u3001\u6570\u636E\u4E00\u81F4\u6027\u3001\u6743\u9650\u8D8A\u6743\u9632\u62A4\\n- \u7981\u6B62\uFF1A\u6A21\u7CCA\u8BCD\uFF08\u5982\u201C\u5927\u6982/\u53EF\u80FD/\u5E94\u8BE5/\u5C3D\u91CF/\u5DEE\u4E0D\u591A\u201D\u7B49\uFF09","remark":"PRD\u6587\u6863\u4E2D\u5305\u542B\u89D2\u8272\u3001\u80CC\u666F\u3001\u8F93\u5165\u53C2\u6570\u3001\u4EFB\u52A1\u3001\u529F\u80FD\u6A21\u5757\u8303\u56F4\u3001\u8F93\u51FA\u8981\u6C42","owner":"17603906431","upvotes":7,"downvotes":0,"upvoteDifference":7,"updatedAt":"2026-06-12T07:07:41.967Z"}')}}]);